const standardEmojiMap = $('get emoji').first().json;
// Extract all custom emoji items into a single array
const customEmojiList = $('get custom emoji').all().map(item => item.json);
const rawInput = $('finish reaction add').item.json.fields[0].value.trim();

const cleanKey = rawInput.replace(/^:|:$/g, '').trim().toLowerCase();
let formattedEmoji = rawInput;

// 1. Standard Unicode shortcode (:skull: -> 💀)
if (standardEmojiMap && standardEmojiMap[cleanKey]) {
  formattedEmoji = standardEmojiMap[cleanKey];
} 
// 2. Raw custom emoji paste (<:Irrenarr:1393810618762526733> -> Irrenarr:1393810618762526733)
else if (/^<a?:[^:]+:\d+>$/.test(rawInput)) {
  formattedEmoji = rawInput.replace(/^<a?:([^:]+:\d+)>$/, '$1');
}
// 3. Typed server custom shortcode (:Irrenarr: -> Irrenarr:1393810618762526733)
else if (Array.isArray(customEmojiList) && customEmojiList.length > 0) {
  const match = customEmojiList.find(e => e.name && e.name.toLowerCase() === cleanKey);
  if (match) {
    formattedEmoji = `${match.name}:${match.id}`;
  }
}

return [{ json: { formattedEmoji } }];

